import React from 'react';
import { motion } from 'framer-motion';

const interests = [
  { emoji: '🏏', label: 'Playing Cricket', desc: 'Team sport & strategy' },
  { emoji: '♟️', label: 'Chess',          desc: 'Tactical thinking'    },
  { emoji: '🍜', label: 'New Cuisines',   desc: 'Exploring world food' },
  { emoji: '✈️', label: 'Travelling',     desc: 'Discovering new places'},
];

const containerVariants = {
  hidden: {},
  show: { transition: { staggerChildren: 0.1 } },
};

const cardVariants = {
  hidden: { opacity: 0, scale: 0.85 },
  show: { opacity: 1, scale: 1, transition: { duration: 0.4, ease: 'easeOut' } },
};

const Interests = () => (
  <motion.section
    className="interests-section"
    initial="hidden"
    whileInView="show"
    viewport={{ once: true, amount: 0.2 }}
    variants={containerVariants}
  >
    <h2>Personal Interests</h2>
    <div className="interests-grid">
      {interests.map((item) => (
        <motion.div key={item.label} className="interest-card" variants={cardVariants}>
          <span className="interest-emoji">{item.emoji}</span>
          <span className="interest-label">{item.label}</span>
          <span className="interest-desc">{item.desc}</span>
        </motion.div>
      ))}
    </div>
  </motion.section>
);

export default Interests;